import sys

def find_dominant_piranha(t, test_cases):
    results = []
    for n, sizes in test_cases:
        found = False
        for i in range(n):
            if (i == 0 or sizes[i] > sizes[i - 1]) and (i == n - 1 or sizes[i] > sizes[i + 1]):
                results.append(i + 1)
                found = True
                break
        if not found:
            results.append(-1)
    return results

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    test_cases = []
    index = 1
    for _ in range(t):
        n = int(data[index])
        sizes = list(map(int, data[index + 1:index + 1 + n]))
        test_cases.append((n, sizes))
        index += 1 + n

    results = find_dominant_piranha(t, test_cases)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
